1	export const ONBOARDING_STEP_COUNT = 7;
2	export const CURRENT_ONBOARDING_VERSION = 3;
3	export const MODEL_DOWNLOAD_STEP = 5;
4	
5	export function normalizeOnboardingStep(
6		step: number,
7		onboardingComplete: boolean,
8		onboardingVersion: number
9	): number {
10		if (onboardingComplete) {
11			return 1;
12		}
13	
14		if (onboardingVersion < CURRENT_ONBOARDING_VERSION) {
15			return 1;
16		}
17	
18		return Math.min(Math.max(step, 1), ONBOARDING_STEP_COUNT);
19	}
