1	import { Result } from "better-result";
2	import { AlertCircle, Check, Mic } from "lucide-solid";
3	import { Show, createSignal, onMount } from "solid-js";
4	import { useI18n } from "../../../i18n";
5	
6	interface MicrophonePermissionStepProps {
7		onPermissionChange: (granted: boolean) => void;
8	}
9	
10	export default function MicrophonePermissionStep(props: MicrophonePermissionStepProps) {
11		const [t] = useI18n();
12		const [isGranted, setIsGranted] = createSignal<boolean | null>(null);
13		const [isRequesting, setIsRequesting] = createSignal(false);
14	
15		const checkPermission = async () => {
16			const result = await Result.tryPromise(() =>
17				navigator.permissions.query({
18					name: "microphone" as PermissionName,
19				})
20			);
21			if (Result.isError(result)) {
22				setIsGranted(false);
23				props.onPermissionChange(false);
24				return;
25			}
26			const granted = result.value.state === "granted";
27			setIsGranted(granted);
28			props.onPermissionChange(granted);
29		};
30	
31		onMount(() => {
32			checkPermission();
33		});
34	
35		const handleRequest = async () => {
36			setIsRequesting(true);
37			const stream = await Result.tryPromise(() =>
38				navigator.mediaDevices.getUserMedia({ audio: true })
39			);
40			if (Result.isOk(stream)) {
41				for (const track of stream.value.getTracks()) {
42					track.stop();
43				}
44				setIsGranted(true);
45				props.onPermissionChange(true);
46			} else {
47				setIsGranted(false);
48				props.onPermissionChange(false);
49			}
50			setIsRequesting(false);
51		};
52	
53		return (
54			<div class="text-center max-w-md mx-auto">
55				{/* Terminal-style header */}
56				<div class="font-mono text-ac text-sm mb-8 tracking-wider">[STEP_01] &gt; MIC_PERMISSION</div>
57	
58				{/* Card container */}
59				<div class="border border-border bg-th-surface p-8">
60					<div class="w-16 h-16 border border-border-strong flex items-center justify-center mx-auto mb-6">
61						<Mic class="w-8 h-8 text-ac" />
62					</div>
63	
64					<h2 class="font-mono text-xl uppercase tracking-wider text-txt-primary mb-3">
65						{t("onboarding.micPermissionTitle")}
66					</h2>
67	
68					<p class="font-mono text-sm text-txt-secondary mb-8">
69						{t("onboarding.micPermissionDescription")}
70					</p>
71	
72					<div class="mb-6">
73						<Show when={isGranted() === null}>
74							<div class="flex items-center justify-center gap-2 font-mono text-sm text-txt-muted">
75								<div class="w-4 h-4 border-2 border-txt-muted border-t-transparent rounded-full animate-spin" />
76								<span>{t("onboarding.checkingPermission")}</span>
77							</div>
78						</Show>
79						<Show when={isGranted() === true}>
80							<div class="flex items-center justify-center gap-2 font-mono text-sm text-success">
81								<Check class="w-5 h-5" />
82								<span>{t("onboarding.micPermissionGranted")}</span>
83							</div>
84						</Show>
85						<Show when={isGranted() === false}>
86							<div class="flex items-center justify-center gap-2 font-mono text-sm text-ac">
87								<AlertCircle class="w-5 h-5" />
88								<span>{t("onboarding.micPermissionNotGranted")}</span>
89							</div>
90						</Show>
91					</div>
92	
93					<Show when={isGranted() !== true}>
94						<button
95							type="button"
96							onClick={handleRequest}
97							disabled={isRequesting() || isGranted() === null}
98							class="px-6 py-3 bg-ac text-ac-on font-mono font-bold uppercase tracking-wider text-sm hover:bg-ac-hover transition-colors disabled:opacity-30"
99						>
100							{isRequesting()
101								? t("onboarding.checkingPermission")
102								: t("onboarding.grantMicPermission")}
103						</button>
104					</Show>
105				</div>
106			</div>
107		);
108	}
