1	import { type UnlistenFn, listen } from "@tauri-apps/api/event";
2	import { Result } from "better-result";
3	import { AlertCircle, Check, ExternalLink, Shield } from "lucide-solid";
4	import { Show, createSignal, onCleanup, onMount } from "solid-js";
5	import { requestAccessibilityPermission } from "tauri-plugin-macos-permissions-api";
6	import { useI18n } from "../../../i18n";
7	import { checkAccessibilityProbe } from "../../../lib/commands/permissions";
8	
9	interface AccessibilityPermissionStepProps {
10		onPermissionChange: (granted: boolean) => void;
11	}
12	
13	export default function AccessibilityPermissionStep(props: AccessibilityPermissionStepProps) {
14		const [t] = useI18n();
15		const [isGranted, setIsGranted] = createSignal<boolean | null>(null);
16		const [isRequesting, setIsRequesting] = createSignal(false);
17		let pollInterval: ReturnType<typeof setInterval> | undefined;
18		let unlistenFn: UnlistenFn | undefined;
19	
20		const markGranted = () => {
21			setIsGranted(true);
22			props.onPermissionChange(true);
23			if (pollInterval) {
24				clearInterval(pollInterval);
25				pollInterval = undefined;
26			}
27		};
28	
29		const checkPermission = async () => {
30			const granted = await checkAccessibilityProbe();
31			if (Result.isError(granted)) {
32				setIsGranted(false);
33				props.onPermissionChange(false);
34				return;
35			}
36			setIsGranted(granted.value);
37			props.onPermissionChange(granted.value);
38			if (granted.value && pollInterval) {
39				clearInterval(pollInterval);
40				pollInterval = undefined;
41			}
42		};
43	
44		const checkWithRetries = async () => {
45			// Try immediately
46			await checkPermission();
47			if (isGranted()) return;
48	
49			// Retry after 200ms (let TCC settle)
50			await new Promise((r) => setTimeout(r, 200));
51			await checkPermission();
52			if (isGranted()) return;
53	
54			// Retry after 500ms more
55			await new Promise((r) => setTimeout(r, 500));
56			await checkPermission();
57			if (isGranted()) return;
58	
59			// Final retry after 1s more — if probes are fully cached,
60			// trust the notification since it only fires on an actual toggle
61			await new Promise((r) => setTimeout(r, 1000));
62			await checkPermission();
63			if (!isGranted()) {
64				// AXIsProcessTrusted can lag behind the Settings notification.
65				// The notification itself is reliable — it fires when the user
66				// toggles the switch. Trust it.
67				markGranted();
68			}
69		};
70	
71		onMount(async () => {
72			await checkPermission();
73	
74			if (!isGranted()) {
75				// Poll as fallback
76				pollInterval = setInterval(checkPermission, 1000);
77	
78				// Listen for macOS distributed notification when the user
79				// toggles accessibility in System Settings
80				unlistenFn = await listen("accessibility-changed", () => {
81					checkWithRetries();
82				});
83			}
84		});
85	
86		onCleanup(() => {
87			if (pollInterval) {
88				clearInterval(pollInterval);
89			}
90			if (unlistenFn) {
91				unlistenFn();
92			}
93		});
94	
95		const handleOpenSettings = async () => {
96			setIsRequesting(true);
97			await Result.tryPromise(() => requestAccessibilityPermission());
98			if (!pollInterval) {
99				pollInterval = setInterval(checkPermission, 1000);
100			}
101			setIsRequesting(false);
102		};
103	
104		return (
105			<div class="text-center max-w-md mx-auto">
106				{/* Terminal-style header */}
107				<div class="font-mono text-ac text-sm mb-8 tracking-wider">
108					[STEP_02] &gt; ACCESSIBILITY_PERMISSION
109				</div>
110	
111				{/* Card container */}
112				<div class="border border-border bg-th-surface p-8">
113					<div class="w-16 h-16 border border-border-strong flex items-center justify-center mx-auto mb-6">
114						<Shield class="w-8 h-8 text-ac" />
115					</div>
116	
117					<h2 class="font-mono text-xl uppercase tracking-wider text-txt-primary mb-3">
118						{t("onboarding.accessibilityTitle")}
119					</h2>
120	
121					<p class="font-mono text-sm text-txt-secondary mb-4">
122						{t("onboarding.accessibilityDescription")}
123					</p>
124	
125					<Show when={isGranted() === false}>
126						<p class="font-mono text-xs text-txt-muted mb-6 border-l-2 border-border-strong pl-3 text-left">
127							{t("onboarding.accessibilityInstructions")}
128						</p>
129					</Show>
130	
131					<div class="mb-6">
132						<Show when={isGranted() === null}>
133							<div class="flex items-center justify-center gap-2 font-mono text-sm text-txt-muted">
134								<div class="w-4 h-4 border-2 border-txt-muted border-t-transparent rounded-full animate-spin" />
135								<span>{t("onboarding.checkingPermission")}</span>
136							</div>
137						</Show>
138						<Show when={isGranted() === true}>
139							<div class="flex items-center justify-center gap-2 font-mono text-sm text-success">
140								<Check class="w-5 h-5" />
141								<span>{t("onboarding.accessibilityGranted")}</span>
142							</div>
143						</Show>
144						<Show when={isGranted() === false}>
145							<div class="flex items-center justify-center gap-2 font-mono text-sm text-ac">
146								<AlertCircle class="w-5 h-5" />
147								<span>{t("onboarding.accessibilityNotGranted")}</span>
148							</div>
149						</Show>
150					</div>
151	
152					<Show when={isGranted() !== true}>
153						<button
154							type="button"
155							onClick={handleOpenSettings}
156							disabled={isRequesting() || isGranted() === null}
157							class="inline-flex items-center gap-2 px-6 py-3 bg-ac text-ac-on font-mono font-bold uppercase tracking-wider text-sm hover:bg-ac-hover transition-colors disabled:opacity-30"
158						>
159							<span>{t("onboarding.openSystemPreferences")}</span>
160							<ExternalLink class="w-4 h-4" />
161						</button>
162					</Show>
163				</div>
164			</div>
165		);
166	}
