61	fn key_from_keycode(keycode: u16) -> Option<SystemKey> {
62	    match keycode {
63	        KEYCODE_FN => Some(SystemKey::Fn),
64	        KEYCODE_LEFT_CONTROL => Some(SystemKey::LeftControl),
65	        KEYCODE_RIGHT_CONTROL => Some(SystemKey::RightControl),
66	        KEYCODE_LEFT_OPTION => Some(SystemKey::LeftOption),
67	        KEYCODE_RIGHT_OPTION => Some(SystemKey::RightOption),
68	        KEYCODE_LEFT_COMMAND => Some(SystemKey::LeftCommand),
69	        KEYCODE_RIGHT_COMMAND => Some(SystemKey::RightCommand),
70	        _ => None,
71	    }
72	}
73	
74	fn key_is_down_in_flags(key: SystemKey, flags: NSEventModifierFlags) -> bool {
75	    match key {
76	        SystemKey::Fn => flags.contains(NSEventModifierFlags::Function),
77	        SystemKey::LeftControl | SystemKey::RightControl => {
78	            flags.contains(NSEventModifierFlags::Control)
79	        }
80	        SystemKey::LeftOption | SystemKey::RightOption => {
81	            flags.contains(NSEventModifierFlags::Option)
82	        }
83	        SystemKey::LeftCommand | SystemKey::RightCommand => {
84	            flags.contains(NSEventModifierFlags::Command)
85	        }
86	    }
87	}
88	
89	fn emit_system_key_event(event: &NSEvent) {
90	    let Some(app_handle) = APP_HANDLE.get() else {
91	        return;
92	    };
93	
94	    let Some(key) = key_from_keycode(event.keyCode()) else {
95	        return;
96	    };
97	
98	    let flags = event.modifierFlags();
99	    let is_down = key_is_down_in_flags(key, flags);
100	    let mut pressed = pressed_keys()
101	        .lock()
102	        .expect("system key pressed state mutex poisoned");
103	
104	    if is_down {
105	        let was_new_key = pressed.insert(key);
106	
107	        if was_new_key {
108	            let _ = app_handle.emit(
109	                "system-key-pressed",
110	                SystemKeyPressedPayload {
111	                    key,
112	                    pressed_keys: pressed.iter().copied().collect(),
113	                },
114	            );
115	        }
116	
117	        return;
118	    }
119	
120	    if pressed.remove(&key) {
121	        let pressed_keys = pressed.iter().copied().collect::<Vec<_>>();
122	        let _ = app_handle.emit(
123	            "system-key-released",
124	            SystemKeyReleasedPayload { key, pressed_keys },
125	        );
126	
127	        if pressed.is_empty() {
128	            let _ = app_handle.emit("system-keys-released", ());
129	        }
130	    }
131	}
132	
133	fn emit_keyboard_key_pressed(event: &NSEvent) {
134	    let Some(app_handle) = APP_HANDLE.get() else {
135	        return;
136	    };
137	
138	    if event.isARepeat() {
139	        return;
140	    }
141	
142	    let key_code = event.keyCode() as i64;
143	    let _ = app_handle.emit(
144	        "keyboard-key-pressed",
145	        KeyboardKeyPressedPayload { key_code },
146	    );
147	}
148	
149	fn handle_event(event: &NSEvent) {
150	    match event.r#type() {
151	        NSEventType::FlagsChanged => emit_system_key_event(event),
152	        NSEventType::KeyDown => emit_keyboard_key_pressed(event),
153	        _ => {}
154	    }
155	}
