12		if (theme === "system") {
13			const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
14			root.classList.toggle("dark", prefersDark);
15		} else {
16			root.classList.toggle("dark", theme === "dark");
17		}
