37	const NUM_BARS = 10;
38	const BAR_INDICES = Array.from({ length: NUM_BARS }, (_, i) => i);
39	const BAR_BASE_HEIGHT = 4;
40	const BAR_MAX_HEIGHT = 18;
41	const BAR_IDLE_AMPLITUDE = 2;
42	const BAR_VOICE_SCALE = 2.5;
43	const WAVE_STEP_MS = 110;
44	const WAVE_PATTERN = [
45		0.25, 0.45, 0.7, 0.9, 1.0, 0.95, 0.75, 0.5, 0.3, 0.4, 0.65, 0.85, 1.0, 0.9, 0.65, 0.35,
46	];
47	
48	const WINDOW_WIDTH_COMPACT = 100;
49	const WINDOW_WIDTH_HANDS_FREE = 140;
50	const WINDOW_HEIGHT = 28;
51	const BOTTOM_PADDING = 20;
52	const ESCAPE_KEY_CODE = 53;
53	const VOXFUSION_BUNDLE_ID = "io.voxfusion.app";
54	
55	type KeyboardKeyPressedPayload = {
56		keyCode: number;
57	};
