59	let lastMonitorX: number | null = null;
60	let lastMonitorY: number | null = null;
61	let currentWindowWidth = WINDOW_WIDTH_COMPACT;
62	
63	async function setWindowWidth(width: number) {
64		if (currentWindowWidth === width) return;
65		currentWindowWidth = width;
66		await getCurrentWindow().setSize(new LogicalSize(width, WINDOW_HEIGHT));
67		lastMonitorX = null;
68		lastMonitorY = null;
69		await repositionToCurrentMonitor();
70	}
71	
72	async function showVoiceControlWindow() {
73		await repositionToCurrentMonitor();
74		await getCurrentWindow().show();
75	}
76	
77	async function hideVoiceControlWindow() {
78		await getCurrentWindow().hide();
79	}
80	
81	async function repositionToCurrentMonitor() {
82		const cursor = await cursorPosition();
83		const monitor = await monitorFromPoint(cursor.x, cursor.y);
84		if (!monitor) return;
85	
86		const pos = monitor.position.toLogical(monitor.scaleFactor);
87		const size = monitor.size.toLogical(monitor.scaleFactor);
88	
89		if (pos.x === lastMonitorX && pos.y === lastMonitorY) return;
90		lastMonitorX = pos.x;
91		lastMonitorY = pos.y;
92	
93		const x = pos.x + (size.width - currentWindowWidth) / 2;
94		const y = pos.y + size.height - WINDOW_HEIGHT - BOTTOM_PADDING;
95	
96		await getCurrentWindow().setPosition(new LogicalPosition(x, y));
97	}
