99	export default function VoiceControl() {
100		const settings = useSettings();
101		const [isRecording, setIsRecording] = createSignal(false);
102		const [loading, setLoading] = createSignal(false);
103		const [currentShortcut, setCurrentShortcut] = createSignal<string | null>(null);
104		const [selectedMicrophone, setSelectedMicrophone] = createSignal<string | null>(null);
105		const [muteMediaWhileRecording, setMuteMediaWhileRecording] = createSignal(false);
106		const [audioLevel, setAudioLevel] = createSignal(0);
107		const [waveOffset, setWaveOffset] = createSignal(0);
108		const [isOnboardingComplete, setIsOnboardingComplete] = createSignal(false);
109		const [isLearningActive, setIsLearningActive] = createSignal(false);
110	
111		createEffect(() => {
112			if (!isRecording()) return;
113			const intervalId = setInterval(() => {
114				setWaveOffset((o) => (o + 1) % WAVE_PATTERN.length);
115			}, WAVE_STEP_MS);
116			onCleanup(() => clearInterval(intervalId));
117		});
118	
119		const barHeight = (index: number) => {
120			if (loading()) return BAR_BASE_HEIGHT;
121			const factor = WAVE_PATTERN[(waveOffset() + index) % WAVE_PATTERN.length]!;
122			const amplitude = BAR_IDLE_AMPLITUDE + audioLevel() * BAR_VOICE_SCALE;
123			return Math.min(BAR_MAX_HEIGHT, BAR_BASE_HEIGHT + factor * amplitude);
124		};
125		const [recordingMode, setRecordingMode] = createSignal<"toggle" | "hold" | null>(null);
126		let isStopping = false;
127		let isStarting = false;
128		let activeAppBundleId: string | null = null;
129		let activeDomain: string | null = null;
130	
131		const canUseShortcut = () => isOnboardingComplete() || isLearningActive();
132	
133		const toggleRecording = () => {
134			if (!canUseShortcut()) return;
135			if (isStarting || isStopping) return;
136	
137			if (isRecording()) {
138				if (recordingMode() !== "toggle") return;
139				stopRecording();
140			} else {
141				startRecording("toggle");
142			}
143		};
144	
145		const startHoldToSpeakRecording = () => {
146			if (!canUseShortcut()) return;
147			if (isStarting || isStopping || isRecording()) return;
148			startRecording("hold");
149		};
150	
151		const stopHoldToSpeakRecording = () => {
152			if (!canUseShortcut()) return;
153			if (isStarting || isStopping || !isRecording()) return;
154			if (recordingMode() !== "hold") return;
155			stopRecording();
156		};
157	
158		const cancelInterruptedHoldToSpeakRecording = () => {
159			if (!canUseShortcut()) return;
160			if (isStarting || isStopping || !isRecording()) return;
161			if (recordingMode() !== "hold") return;
162			cancelRecording();
163		};
164	
165		const registerShortcuts = async (toggleShortcut: string, holdShortcut: string) => {
166			const toggleHotkey = { hotkey: toggleShortcut, onPressed: toggleRecording };
167			const holdHotkey = {
168				hotkey: holdShortcut,
169				onPressed: startHoldToSpeakRecording,
170				onReleased: stopHoldToSpeakRecording,
171			};
172			const hotkeys = toggleShortcut === holdShortcut ? [toggleHotkey] : [toggleHotkey, holdHotkey];
173	
174			await registerDictationHotkeys(hotkeys);
175			setCurrentShortcut(`${toggleShortcut}|${holdShortcut}`);
176		};
177	
178		const unregisterShortcuts = async () => {
179			if (currentShortcut() === null) return;
180			await unregisterDictationHotkey();
181			setCurrentShortcut(null);
182		};
183	
184		onMount(async () => {
185			await repositionToCurrentMonitor();
186			const repositionInterval = setInterval(repositionToCurrentMonitor, 1000);
187			onCleanup(() => clearInterval(repositionInterval));
188	
189			const settings = await loadSettings();
190			let hotkey = settings.hotkey;
191			if (!isValidHotkey(hotkey)) {
192				hotkey = DEFAULT_HOTKEY;
193				await updateHotkey(hotkey);
194			}
195			let holdToSpeakHotkey = settings.holdToSpeakHotkey;
196			if (!isValidHotkey(holdToSpeakHotkey)) {
197				holdToSpeakHotkey = DEFAULT_HOLD_TO_SPEAK_HOTKEY;
198				await updateHoldToSpeakHotkey(holdToSpeakHotkey);
199			}
200			setSelectedMicrophone(settings.selectedMicrophoneId);
201			setMuteMediaWhileRecording(settings.muteMediaWhileRecording);
202			setIsOnboardingComplete(settings.onboardingComplete);
203			if (settings.onboardingComplete) {
204				await registerShortcuts(hotkey, holdToSpeakHotkey);
205			}
206	
207			const unlistenSettings = await listen("settings-changed", async () => {
208				const newSettings = await loadSettings();
209				const newHotkey = isValidHotkey(newSettings.hotkey) ? newSettings.hotkey : DEFAULT_HOTKEY;
210				const newHoldToSpeakHotkey = isValidHotkey(newSettings.holdToSpeakHotkey)
211					? newSettings.holdToSpeakHotkey
212					: DEFAULT_HOLD_TO_SPEAK_HOTKEY;
213				const wasOnboarding = !isOnboardingComplete();
214				const nowComplete = newSettings.onboardingComplete;
215				const shouldRegisterShortcuts = nowComplete || isLearningActive();
216				const shortcutKey = `${newHotkey}|${newHoldToSpeakHotkey}`;
217				if (
218					shouldRegisterShortcuts &&
219					(shortcutKey !== currentShortcut() || (wasOnboarding && nowComplete))
220				) {
221					await registerShortcuts(newHotkey, newHoldToSpeakHotkey);
222				} else if (!shouldRegisterShortcuts) {
223					await unregisterShortcuts();
224				}
225				setSelectedMicrophone(newSettings.selectedMicrophoneId);
226				setMuteMediaWhileRecording(newSettings.muteMediaWhileRecording);
227				setIsOnboardingComplete(newSettings.onboardingComplete);
228			});
229	
230			const unlistenAudio = await listen<number>("audio-level", (event) => {
231				setAudioLevel(event.payload);
232			});
233	
234			const unlistenLearning = await listen<boolean>("learning-step-active", async (event) => {
235				const active = event.payload;
236				setIsLearningActive(active);
237				const newSettings = await loadSettings();
238				const newHotkey = isValidHotkey(newSettings.hotkey) ? newSettings.hotkey : DEFAULT_HOTKEY;
239				const newHoldToSpeakHotkey = isValidHotkey(newSettings.holdToSpeakHotkey)
240					? newSettings.holdToSpeakHotkey
241					: DEFAULT_HOLD_TO_SPEAK_HOTKEY;
242				if (active || isOnboardingComplete()) {
243					const shortcutKey = `${newHotkey}|${newHoldToSpeakHotkey}`;
244					if (shortcutKey !== currentShortcut()) {
245						await registerShortcuts(newHotkey, newHoldToSpeakHotkey);
246					}
247				} else {
248					await unregisterShortcuts();
249				}
250			});
251	
252			const unlistenKeyboardKeyPressed = await listen<KeyboardKeyPressedPayload>(
253				"keyboard-key-pressed",
254				(event) => {
255					if (event.payload.keyCode === ESCAPE_KEY_CODE) return;
256					if (recordingMode() !== "hold") return;
257					cancelInterruptedHoldToSpeakRecording();
258				}
259			);
260	
261			onCleanup(() => {
262				unlistenSettings();
263				unlistenAudio();
264				unlistenLearning();
265				unlistenKeyboardKeyPressed();
266			});
267		});
268	
269		onCleanup(async () => {
270			if (isRecording()) {
271				await cancelRecording();
272			}
273			await unregisterEscapeShortcut();
274			await unregisterDictationHotkey();
275			setCurrentShortcut(null);
276		});
277	
278		const stopRecording = async () => {
279			if (isStopping) return;
280			if (!isRecording()) return;
281	
282			logDiagnostic("info", "voice", "stop_recording_started", {
283				mode: recordingMode(),
284			});
285			isStopping = true;
286			setIsRecording(false);
287			setRecordingMode(null);
288			await unregisterEscapeShortcut();
289			await setWindowWidth(WINDOW_WIDTH_COMPACT);
290	
291			const completed = await Result.tryPromise(async () => {
292				const filePath = await stopRecordingWithDevice();
293				if (Result.isError(filePath)) {
294					logDiagnostic("error", "voice", "stop_recording_failed", errorFields(filePath.error));
295					return;
296				}
297				await restoreMediaAfterRecording();
298	
299				setLoading(true);
300	
301				const bundleId = activeAppBundleId;
302				const domain = activeDomain;
303				activeAppBundleId = null;
304				activeDomain = null;
305				const result = await transcribeAudio(
306					filePath.value,
307					bundleId,
308					domain,
309					settings().defaultStyle
310				);
311				if (Result.isError(result)) {
312					logDiagnostic("error", "voice", "transcription_failed", errorFields(result.error));
313					return;
314				}
315				await saveTranscription(result.value);
316				logDiagnostic("info", "voice", "transcription_completed", {
317					wordCount: result.value.word_count,
318					processingTimeMs: result.value.processing_time_ms,
319					audioDurationMs: result.value.audio_duration_ms,
320					hasAppContext: Boolean(bundleId),
321					hasSiteContext: Boolean(domain),
322					style: settings().defaultStyle,
323				});
324	
325				await typeText(result.value.text ?? "");
326				logDiagnostic("info", "voice", "text_typed", {
327					characterCount: result.value.text?.length ?? 0,
328				});
329	
330				setTimeout(() => {
331					emit("transcription-created");
332				}, 1000);
333			});
334			if (Result.isError(completed)) {
335				logDiagnostic("error", "voice", "stop_recording_unhandled_failure", {
336					error: errorFields(completed.error),
337				});
338				console.error("Failed to stop recording:", completed.error);
339			}
340			await restoreMediaAfterRecording();
341			setLoading(false);
342			isStopping = false;
343			await hideVoiceControlWindow();
344			logDiagnostic("info", "voice", "stop_recording_completed");
345		};
346	
347		const registerEscapeShortcut = async () => {
348			await Result.tryPromise(async () => {
349				await register("Escape", (evt) => {
350					if (evt.state !== "Pressed") return;
351					cancelRecording();
352				});
353			});
354		};
355	
356		const unregisterEscapeShortcut = async () => {
357			await Result.tryPromise(() => unregister("Escape"));
358		};
359	
360		const cancelRecording = async () => {
361			if (isStopping) return;
362			if (!isRecording()) return;
363	
364			logDiagnostic("warn", "voice", "recording_cancelled", {
365				mode: recordingMode(),
366			});
367			isStopping = true;
368			setIsRecording(false);
369			setRecordingMode(null);
370			activeAppBundleId = null;
371			activeDomain = null;
372			await unregisterEscapeShortcut();
373			await setWindowWidth(WINDOW_WIDTH_COMPACT);
374	
375			await stopRecordingWithDevice();
376			await restoreMediaAfterRecording();
377			isStopping = false;
378			await hideVoiceControlWindow();
379		};
380	
381		const muteMediaForRecording = async () => {
382			if (!muteMediaWhileRecording()) return;
383			await muteMediaForRecordingCommand();
384		};
385	
386		const restoreMediaAfterRecording = async () => {
387			await restoreMediaAfterRecordingCommand();
388		};
389	
390		const startRecording = async (mode: "toggle" | "hold") => {
391			const startedRecording = await Result.tryPromise(async () => {
392				if (isRecording()) return;
393				if (isStopping || isStarting) return;
394				isStarting = true;
395				logDiagnostic("info", "voice", "start_recording_started", { mode });
396				activeAppBundleId = null;
397				activeDomain = null;
398				const frontmost = await getFrontmostApp();
399				if (Result.isOk(frontmost)) {
400					if (frontmost.value?.bundle_id && frontmost.value.bundle_id !== VOXFUSION_BUNDLE_ID) {
401						activeAppBundleId = frontmost.value.bundle_id;
402						activeDomain = frontmost.value.domain ?? null;
403					}
404				}
405				await setWindowWidth(mode === "toggle" ? WINDOW_WIDTH_HANDS_FREE : WINDOW_WIDTH_COMPACT);
406				await showVoiceControlWindow();
407	
408				const deviceName = selectedMicrophone();
409				const started = await startRecordingWithDevice(deviceName === "default" ? null : deviceName);
410				if (Result.isError(started)) {
411					logDiagnostic("error", "voice", "start_recording_failed", {
412						error: errorFields(started.error),
413						hasSelectedMicrophone: Boolean(deviceName && deviceName !== "default"),
414					});
415					await hideVoiceControlWindow();
416					isStarting = false;
417					return;
418				}
419				void muteMediaForRecording();
420				setRecordingMode(mode);
421				setIsRecording(true);
422				isStarting = false;
423				await registerEscapeShortcut();
424				logDiagnostic("info", "voice", "start_recording_completed", {
425					mode,
426					hasAppContext: Boolean(activeAppBundleId),
427					hasSiteContext: Boolean(activeDomain),
428					hasSelectedMicrophone: Boolean(deviceName && deviceName !== "default"),
429				});
430			});
431			if (Result.isError(startedRecording)) {
432				logDiagnostic("error", "voice", "start_recording_unhandled_failure", {
433					error: errorFields(startedRecording.error),
434				});
435				await hideVoiceControlWindow();
436				isStopping = false;
437				isStarting = false;
438			}
439		};
440	
441		return (
442			<div
443				class={`min-h-2 mx-auto w-fit bg-th-base h-full rounded-2xl border border-border-strong flex align-center justify-center py-1 ${recordingMode() === "toggle" ? "px-2" : "px-4"} ${!isRecording() && !loading() ? "opacity-0" : ""}`}
444			>
445				<Show when={isRecording() && recordingMode() === "toggle" && !loading()}>
446					<button
447						type="button"
448						aria-label="Cancel transcription"
449						onClick={() => cancelRecording()}
450						class="w-4 h-4 mr-1 self-center flex items-center justify-center rounded-full bg-th-elevated text-txt-secondary hover:text-txt-primary hover:bg-th-hover transition-colors cursor-pointer"
451					>
452						<X size={10} />
453					</button>
454				</Show>
455				<Show when={isRecording() || loading()}>
456					<div class="flex items-center justify-center gap-[2px]">
457						<For each={BAR_INDICES}>
458							{(index) => (
459								<div
460									class="w-[2px] rounded-full bg-ac transition-[height] duration-200 ease-out"
461									style={{ height: `${barHeight(index)}px` }}
462								/>
463							)}
464						</For>
465					</div>
466				</Show>
467				<Show when={isRecording() && recordingMode() === "toggle" && !loading()}>
468					<button
469						type="button"
470						aria-label="End transcription"
471						onClick={() => stopRecording()}
472						class="w-4 h-4 ml-1 self-center flex items-center justify-center rounded-full bg-ac text-ac-on hover:bg-ac-hover transition-colors cursor-pointer"
473					>
474						<Check size={10} />
475					</button>
476				</Show>
477				<div
478					class="overflow-hidden transition-[max-width] duration-300 ease-out flex items-center"
479					style={{ "max-width": loading() ? "24px" : "0px" }}
480				>
481					<DotMatrixSpinner class="text-ac ml-2" size={16} dotSize={3} />
482				</div>
483			</div>
484		);
485	}
